import{_ as a,c as n,o as t,j as e,af as o,a as r,bD as l}from"./chunks/framework.Bh0MRgqj.js";const m=JSON.parse('{"title":"Debugging in C++ with GDB","description":"","frontmatter":{},"headers":[],"relativePath":"lectures/09-debugging.md","filePath":"lectures/09-debugging.md","lastUpdated":1758773115000}'),s={name:"lectures/09-debugging.md"};function d(c,i,g,p,h,u){return t(),n("div",null,[...i[0]||(i[0]=[e("h1",{id:"debugging-in-c-with-gdb",tabindex:"-1"},[r("Debugging in C++ with GDB "),e("a",{class:"header-anchor",href:"#debugging-in-c-with-gdb","aria-label":"Permalink to “Debugging in C++ with GDB”"},"​")],-1),e("div",{class:"youtube"},[e("div",null,[e("iframe",{width:"853",height:"480",src:"https://www.youtube-nocookie.com/embed/LPQ79whuVFI?rel=0&showinfo=0",title:"CSCI 315",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:"allowfullscreen"})])],-1),o('<h2 id="debugging-with-gdb" tabindex="-1">Debugging with GDB <a class="header-anchor" href="#debugging-with-gdb" aria-label="Permalink to “Debugging with GDB”">​</a></h2><h3 id="what-is-gdb" tabindex="-1">What is GDB? <a class="header-anchor" href="#what-is-gdb" aria-label="Permalink to “What is GDB?”">​</a></h3><ul><li><p><em><strong>GDB</strong></em> stands for <em><strong>GNU Project Debugger</strong></em> and was first written in 1986.</p></li><li><p>A debugging tool for C++ (and other languages).</p></li></ul><figure><img src="'+l+`" alt="Logo for GDB"><figcaption>Logo for GDB</figcaption></figure><ul><li><p>Lets you step through the code one instruction at a time to see what is happening.</p></li><li><p>Loads executable files that were compiled with debug information (<code>-g</code>).</p></li></ul><h3 id="compiling-a-program-for-debugging" tabindex="-1">Compiling a Program for Debugging <a class="header-anchor" href="#compiling-a-program-for-debugging" aria-label="Permalink to “Compiling a Program for Debugging”">​</a></h3><p><code>g++ -g &lt;source&gt; -o &lt;executable&gt;</code></p><h3 id="launching-and-exiting-gdb" tabindex="-1">Launching and Exiting GDB <a class="header-anchor" href="#launching-and-exiting-gdb" aria-label="Permalink to “Launching and Exiting GDB”">​</a></h3><ul><li><code>gdb</code> Start GDB.</li><li><code>gdb &lt;program&gt;</code> Start GDB.</li><li><code>gdb --args</code> Start GDB and pass arguments to executable.</li><li><code>quit</code> Exit GDB.</li></ul><h3 id="run-a-program-to-be-debugged" tabindex="-1">Run a Program to be Debugged <a class="header-anchor" href="#run-a-program-to-be-debugged" aria-label="Permalink to “Run a Program to be Debugged”">​</a></h3><ul><li><code>run</code> Run the executable that was previously set.</li><li><code>file</code> Set the executable to run.</li></ul><h3 id="breakpoints" tabindex="-1">Breakpoints <a class="header-anchor" href="#breakpoints" aria-label="Permalink to “Breakpoints”">​</a></h3><ul><li><code>break &lt;where&gt;</code> Set a new breakpoint.</li><li><code>enable &lt;breakpoint#&gt;</code> Enable a disabled breakpoint</li><li><code>disable &lt;breakpoint#&gt;</code> Disable a breakpoint.</li><li><code>delete &lt;breakpoint#&gt;</code> Remove a breakpoint.</li><li><code>clear</code> Delete all breakpoints.</li></ul><h3 id="stepping-through-lines-of-code" tabindex="-1">Stepping through Lines of Code <a class="header-anchor" href="#stepping-through-lines-of-code" aria-label="Permalink to “Stepping through Lines of Code”">​</a></h3><ul><li><code>step</code> Go to next instruction (source line), diving into function calls.</li><li><code>next</code> Go to next instruction (source line) in this function.</li><li><code>continue</code> Continue execution until the next breakpoint.</li><li><code>finish</code> Continue until the current function returns.</li></ul><h3 id="variables-and-memory" tabindex="-1">Variables and Memory <a class="header-anchor" href="#variables-and-memory" aria-label="Permalink to “Variables and Memory”">​</a></h3><ul><li><code>print</code> Print content of variable/memory location.</li><li><code>display</code> Like <code>print</code> but shows the information with each step.</li><li><code>undisplay</code> Remove the <code>display</code> with the given number.</li><li><code>info locals</code> Print the local variables or arguments in the current stack frame.</li></ul><h2 id="gdb-in-vscodium-or-vs-code" tabindex="-1">GDB in VSCodium or VS Code <a class="header-anchor" href="#gdb-in-vscodium-or-vs-code" aria-label="Permalink to “GDB in VSCodium or VS Code”">​</a></h2><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h3><ol><li><p>Install the <a href="https://open-vsx.org/extension/KylinIdeTeam/cppdebug" target="_blank" rel="noreferrer">C/C++ Debug (gdb)</a> extension.</p></li><li><p>If running in WSL, install the <a href="https://open-vsx.org/extension/jeanp413/open-remote-wsl" target="_blank" rel="noreferrer">Open Remote - WSL</a> extension.</p><ul><li>Ensure that the <a href="https://open-vsx.org/extension/KylinIdeTeam/cppdebug" target="_blank" rel="noreferrer">C/C++ Debug (gdb)</a> extension is installed within WSL.</li></ul></li><li><p>Open the lab/project folder (not just a source file or the whole repository).</p><ul><li>If using WSL, make sure to connect to WSL (remote connection).</li></ul></li><li><p>Open a C++ file.</p></li></ol><h3 id="project-setup" tabindex="-1">Project Setup <a class="header-anchor" href="#project-setup" aria-label="Permalink to “Project Setup”">​</a></h3><ol><li><p>Open a C++ File in the Folder.</p></li><li><p>Click on the “Run” menu at the top.</p></li><li><p>Click on the “Add Configuration” menu item and select “G++ (GDB/LLDB)”.</p></li><li><p>Click “Add Configuration” on the bottom right.</p></li><li><p>Select “C/C++: (gdb) Launch”.</p></li><li><p>Modify the “name”, “program”, “args”, and “cwd” fields as desired.</p></li></ol><p><a href="https://code.visualstudio.com/docs/cpp/launch-json-reference" target="_blank" rel="noreferrer">https://code.visualstudio.com/docs/cpp/launch-json-reference</a></p><h3 id="use-gitignore-files" tabindex="-1">Use <code>.gitignore</code> files <a class="header-anchor" href="#use-gitignore-files" aria-label="Permalink to “Use .gitignore files”">​</a></h3><p>There are often files you do not want to share (executable, debug configuration).</p><p>Git will not track files and folders specified in a <code>.gitignore</code> file.</p><div class="language-plain line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.vscode/*</span></span>
<span class="line"><span>obj/*</span></span>
<span class="line"><span>main</span></span>
<span class="line"><span>test-runner</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div>`,27)])])}const f=a(s,[["render",d]]);export{m as __pageData,f as default};
